dict.string:
.navbar {
	font-family: 'Helvetica Neue', Arial, sans-serif;
	font-size: .85em;
	color: #999;
	margin: 0px;
	line-height: 20px;
	font-weight: bold;
}

.navbar-bg {
	text-align: center;
	padding: 0px;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0px 15px 0px 10px;
}


li a {
	text-decoration: none;
	color: #999;
}

li a:visited {
	text-decoration: none;
	color: #999;
}

li a:hover{
 	color: #F00;
	text-decoration: none;}


li.current-page a{	 color: #666;
	text-decoration: none;}
